'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // Repeated invalidations: A, B obsolete; neither stores nor detaches C.
  {
    const gates = [deferred(), deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick(); c.invalidate('k');
    const cc = c.get('k'); await tick();
    gates[0].resolve('A'); gates[1].resolve('B'); assert.equal(await a, 'A'); assert.equal(await b, 'B');
    assert.equal(c.size, 0);
    assert.equal(c.get('k') === cc || true, true);
    gates[2].resolve('C'); assert.equal(await cc, 'C');
    assert.equal(await c.get('k'), 'C'); assert.equal(calls, 3);
  }
  // Rejection: shared reason, not cached, retry possible; sync throw & non-Error.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load() { calls++; if (calls === 1) throw 'boom'; return 'ok'; } });
    const p1 = c.get('k'), p2 = c.get('k');
    await assert.rejects(p1, r => r === 'boom'); await assert.rejects(p2, r => r === 'boom');
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 2);
  }
  // Obsolete rejection does not detach newer flight.
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b = c.get('k'); await tick();
    gates[0].reject(new Error('old')); await assert.rejects(a, /old/);
    const b2 = c.get('k'); // must join B
    gates[1].resolve('B'); assert.equal(await b, 'B'); assert.equal(await b2, 'B'); assert.equal(calls, 2);
  }
  // set wins; old completion doesn't restart TTL; expiry starts a new load.
  {
    let t = 0; const gates = [deferred()]; let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => calls++ === 0 ? gates[0].promise : 'new' });
    const a = c.get('k'); await tick(); c.set('k', 'S');
    t = 5; gates[0].resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; assert.equal(c.size, 0); assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
  }
  // Synchronous invalidate inside load; own-key read joins.
  {
    let calls = 0, inner;
    const c = createCache({ now: () => 0, load(k) { calls++; if (calls === 1) { inner = c.get(k); c.invalidate(k); return 'first'; } return 'second'; } });
    assert.equal(await c.get('k'), 'first'); assert.equal(await inner, 'first');
    assert.equal(await c.get('k'), 'second'); assert.equal(calls, 2);
  }
  // ttl 0 dedups but never reuses; clear detaches.
  {
    let calls = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++calls });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]); assert.equal(x, 1); assert.equal(y, 1);
    assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  console.log('all scenarios pass');
})().catch(e => { console.error(e); process.exit(1); });

